import type {
  AccordionItemContentProps,
  AccordionItemTriggerProps,
  AccordionItemProps as AccordionPrimitiveItemProps,
  AccordionRootProps,
} from "@ark-ui/react/accordion";
import { Accordion as AccordionPrimitive } from "@ark-ui/react/accordion";
import { CaretDownIcon } from "@phosphor-icons/react";
import { accordionItemRecipe } from "@pisagor/recipes/accordion";
import type { ReactNode } from "react";
import { AccordionItemContext, useAccordionItem } from "./accordion.context";

// #region Types
export interface AccordionItemProps extends AccordionPrimitiveItemProps {
  /**
   * Style recipe. Defaults to `accordionItemRecipe` from `@pisagor/recipes/accordion`.
   *
   * @defaultValue accordionItemRecipe
   */
  itemRecipe?: typeof accordionItemRecipe;
}

interface AccordionPresetItem {
  value: string;
  title: ReactNode;
  content: ReactNode;
  disabled?: boolean;
}

export interface AccordionProps extends Omit<AccordionRootProps, "children"> {
  items?: AccordionPresetItem[];
}
// #endregion

// #region Parts
export function AccordionRoot({ collapsible = true, children, ...rest }: AccordionRootProps) {
  return (
    <AccordionPrimitive.Root {...rest} collapsible={collapsible}>
      {children}
    </AccordionPrimitive.Root>
  );
}

export function AccordionItem({
  children,
  itemRecipe = accordionItemRecipe,
  className,
  ...rest
}: AccordionItemProps) {
  const slots = itemRecipe();

  return (
    <AccordionItemContext value={{ slots }}>
      <AccordionPrimitive.Item {...rest} className={slots.base({ className })}>
        {children}
      </AccordionPrimitive.Item>
    </AccordionItemContext>
  );
}

export function AccordionItemTrigger({ children, className, ...rest }: AccordionItemTriggerProps) {
  const { slots } = useAccordionItem();

  return (
    <AccordionPrimitive.ItemTrigger {...rest} className={slots.trigger({ className })}>
      {children}

      <AccordionPrimitive.ItemIndicator>
        <CaretDownIcon className={slots.indicator()} />
      </AccordionPrimitive.ItemIndicator>
    </AccordionPrimitive.ItemTrigger>
  );
}

export function AccordionItemContent({ children, className, ...rest }: AccordionItemContentProps) {
  const { slots } = useAccordionItem();

  return (
    <AccordionPrimitive.ItemContent {...rest} className={slots.content({ className })}>
      <div className={slots.body()}>{children}</div>
    </AccordionPrimitive.ItemContent>
  );
}
// #endregion

// #region Shorthand
export function AccordionShorthand({ items, ...rest }: AccordionProps) {
  return (
    <AccordionRoot {...rest}>
      {items?.map((item) => (
        <AccordionItem disabled={item.disabled} key={item.value} value={item.value}>
          <AccordionItemTrigger>{item.title}</AccordionItemTrigger>
          <AccordionItemContent>{item.content}</AccordionItemContent>
        </AccordionItem>
      ))}
    </AccordionRoot>
  );
}
// #endregion

// #region Display Names
AccordionRoot.displayName = "Accordion.Root";
AccordionItem.displayName = "Accordion.Item";
AccordionItemTrigger.displayName = "Accordion.ItemTrigger";
AccordionItemContent.displayName = "Accordion.ItemContent";
AccordionShorthand.displayName = "Accordion";
// #endregion

import type { AccordionItemRecipe } from "@pisagor/recipes/accordion";
import { createContext } from "../../utils";

interface AccordionItemContextValue {
  slots: AccordionItemRecipe;
}

export const { AccordionItemContext, useAccordionItem } =
  createContext<AccordionItemContextValue>()({
    name: "AccordionItem",
  });

import {
  AccordionItem,
  AccordionItemContent,
  AccordionItemTrigger,
  AccordionRoot,
  AccordionShorthand,
} from "./accordion";

export type {
  AccordionItemContentProps,
  AccordionItemProps,
  AccordionItemTriggerProps,
  AccordionRootProps,
} from "@ark-ui/react/accordion";

export type { AccordionProps } from "./accordion";

export const Accordion = Object.assign(AccordionShorthand, {
  Item: AccordionItem,
  ItemContent: AccordionItemContent,
  ItemTrigger: AccordionItemTrigger,
  Root: AccordionRoot,
});

import { Portal, useHotkey } from "@ark-ui/react";
import { ark } from "@ark-ui/react/factory";
import { Presence } from "@ark-ui/react/presence";
import { useUncontrolled } from "@mantine/hooks";
import { XIcon } from "@phosphor-icons/react";
import { actionBarRecipe } from "@pisagor/recipes/action-bar";
import type { ComponentProps, MouseEvent, PropsWithChildren, ReactNode } from "react";
import { useCallback, useMemo } from "react";
import { Badge, type BadgeProps } from "../badge";
import { Button } from "../button";
import { Separator, type SeparatorProps } from "../separator";
import { ActionBarContext, type ActionBarContextValue, useActionBar } from "./action-bar.context";

// #region Types
interface ActionBarActionItem {
  /** Icon rendered before the label */
  icon?: ReactNode;
  /** Button label */
  label: string;
  /** Called when the button is clicked */
  onClick: () => void;
  /** Whether the button is disabled */
  disabled?: boolean;
}

export interface ActionBarProps extends Pick<ActionBarContextValue, "lazyMount" | "unmountOnExit"> {
  /**
   * Style recipe. Defaults to `actionBarRecipe` from `@pisagor/recipes/action-bar`.
   *
   * @defaultValue actionBarRecipe
   */
  recipe?: typeof actionBarRecipe;

  /**
   * Whether to close the action bar when the Escape key is pressed.
   *
   * @defaultValue true
   */
  closeOnEscape?: boolean;
  /**
   * The default open state of the action bar.
   *
   * @remarks
   * Ignored when `open` is set.
   */
  defaultOpen?: boolean;
  /**
   * The open state of the action bar.
   *
   * @remarks
   * When set, `defaultOpen` is ignored. Pair with `onOpenChange` to handle updates.
   */
  open?: boolean;
  /** Placement and gutter of the action bar. */
  positioning?: ActionBarContextValue["positioning"];
  /** Action buttons rendered inside the auto-generated ActionBar.Content */
  actions?: ActionBarActionItem[];
  /** Number of selected items rendered via ActionBar.Value */
  count?: number;
  /** The function to call when the open state of the action bar changes. */
  onOpenChange?: (open: boolean) => void;
}

export type ActionBarTriggerProps = ComponentProps<typeof ark.button>;

export type ActionBarContentProps = ComponentProps<typeof ark.div>;

export type ActionBarSeparatorProps = SeparatorProps;

export type ActionBarCloseProps = ComponentProps<typeof ark.button>;

export interface ActionBarValueProps extends BadgeProps {
  /** The number of items selected */
  count: number;
  /** The label of the selection trigger */
  label?: string;
}

export type ActionBarBodyProps = ComponentProps<typeof ark.div>;
// #endregion

// #region Constants
const defaultPositioning = { gutter: "16px", placement: "bottom" } as const;
// #endregion

// #region Parts
export function ActionBarRoot({
  closeOnEscape = true,
  count,
  defaultOpen = false,
  lazyMount,
  open,
  positioning: positioningProp,
  unmountOnExit,
  actions,
  children,
  onOpenChange,
  recipe = actionBarRecipe,
}: PropsWithChildren<ActionBarProps>) {
  const [isOpen, setOpen] = useUncontrolled({
    defaultValue: defaultOpen,
    finalValue: false,
    onChange: onOpenChange,
    value: open,
  });

  const handleClose = useCallback(() => {
    setOpen(false);
  }, [setOpen]);

  const handleOpen = useCallback(() => {
    setOpen(true);
  }, [setOpen]);

  useHotkey({
    action: (event) => {
      if (event.defaultPrevented) {
        return;
      }

      handleClose();
    },
    enabled: isOpen && closeOnEscape,
    hotkey: "Escape",
  });

  const positioning = useMemo(
    () => ({
      ...defaultPositioning,
      ...positioningProp,
    }),
    [positioningProp],
  );

  const slots = useMemo(
    () =>
      recipe({
        placement: positioning.placement,
      }),
    [positioning.placement, recipe],
  );

  const context = useMemo(
    () => ({
      isOpen,
      lazyMount,
      onClose: handleClose,
      onOpen: handleOpen,
      positioning,
      slots,
      unmountOnExit,
    }),
    [handleClose, handleOpen, isOpen, lazyMount, positioning, slots, unmountOnExit],
  );

  const hasPreset = count !== undefined || (actions && actions.length > 0);

  return (
    <ActionBarContext value={context}>
      {children}
      {hasPreset && (
        <ActionBarContent>
          {count !== undefined && <ActionBarValue count={count} />}
          {count !== undefined && actions && <ActionBarSeparator />}
          {actions && (
            <ActionBarBody>
              {actions.map((action) => (
                <Button
                  disabled={action.disabled}
                  key={action.label}
                  onClick={action.onClick}
                  size="sm"
                  variant="ghost"
                >
                  {action.icon}
                  {action.label}
                </Button>
              ))}
            </ActionBarBody>
          )}
          {actions && <ActionBarSeparator />}
          <ActionBarClose>
            <XIcon aria-hidden />
          </ActionBarClose>
        </ActionBarContent>
      )}
    </ActionBarContext>
  );
}

export function ActionBarTrigger({ onClick, ...rest }: ActionBarTriggerProps) {
  const { onOpen, isOpen } = useActionBar();

  const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
    onOpen?.();
    onClick?.(event);
  };

  return (
    <ark.button
      {...rest}
      aria-expanded={isOpen}
      data-part="trigger"
      data-scope="action-bar"
      data-state={isOpen ? "open" : "closed"}
      onClick={handleClick}
      type="button"
    />
  );
}

export function ActionBarContent({
  "aria-labelledby": ariaLabelledby,
  className,
  ...rest
}: ActionBarContentProps) {
  const { isOpen, lazyMount, unmountOnExit, positioning, slots } = useActionBar();

  const placement = positioning.placement;
  const gutter = positioning.gutter;

  return (
    <Portal>
      <Presence asChild lazyMount={lazyMount} present={isOpen} unmountOnExit={unmountOnExit}>
        <ark.div
          className={slots.positioner({ placement })}
          data-part="positioner"
          data-placement={placement}
          data-scope="action-bar"
          style={{ "--gutter": gutter }}
        >
          <ark.div
            {...rest}
            aria-labelledby={ariaLabelledby}
            className={slots.content({ className })}
            data-part="content"
            data-scope="action-bar"
            role="toolbar"
          />
        </ark.div>
      </Presence>
    </Portal>
  );
}

export function ActionBarSeparator({ className, ...rest }: ActionBarSeparatorProps) {
  const { slots } = useActionBar();

  return (
    <Separator
      {...rest}
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="action-bar"
      orientation="vertical"
    />
  );
}

export function ActionBarClose({ onClick, className, ...rest }: ActionBarCloseProps) {
  const { onClose, isOpen, slots } = useActionBar();

  const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
    onClose?.();
    onClick?.(event);
  };

  return (
    <ark.button
      {...rest}
      aria-label="Close"
      className={slots.close({ className })}
      data-part="close"
      data-scope="action-bar"
      data-state={isOpen ? "open" : "closed"}
      onClick={handleClick}
      type="button"
    />
  );
}

export function ActionBarValue({
  count = 0,
  children,
  label,
  className,
  ...rest
}: ActionBarValueProps) {
  const { slots } = useActionBar();

  return (
    <Badge
      {...rest}
      className={slots.value({ className })}
      data-part="value"
      data-scope="action-bar"
      variant="secondary"
    >
      {children ?? label ?? count}
    </Badge>
  );
}

export function ActionBarBody({ className, ...rest }: ActionBarBodyProps) {
  const { slots } = useActionBar();

  return <ark.div {...rest} className={slots.body({ className })} />;
}
// #endregion

// #region Display Names
ActionBarRoot.displayName = "ActionBar";
ActionBarTrigger.displayName = "ActionBar.Trigger";
ActionBarContent.displayName = "ActionBar.Content";
ActionBarSeparator.displayName = "ActionBar.Separator";
ActionBarClose.displayName = "ActionBar.Close";
ActionBarValue.displayName = "ActionBar.Value";
ActionBarBody.displayName = "ActionBar.Body";
// #endregion

import type { ActionBarRecipe } from "@pisagor/recipes/action-bar";
import { createContext } from "../../utils";

interface ActionBarPositioning {
  /**
   * The gutter from the edge in pixels.
   *
   * @defaultValue '16px'
   */
  gutter?: string;
  /**
   * The placement of the action bar.
   *
   * @defaultValue "bottom"
   */
  placement?: "bottom" | "bottom-start" | "bottom-end";
}

export interface ActionBarContextValue {
  /** The open state of the action bar */
  isOpen?: boolean;
  /** Whether to lazy mount the action bar */
  lazyMount?: boolean;
  /** The function to call when the action bar is closed */
  onClose?: () => void;
  /** The function to call when the action bar is opened */
  onOpen?: () => void;
  /** The positioning of the action bar. */
  positioning: ActionBarPositioning;
  /** Slot class recipes from `actionBarRecipe`. */
  slots: ActionBarRecipe;
  /** The function to call when the action bar is mounted */
  unmountOnExit?: boolean;
}

/**
 * Returns the nearest action bar context.
 */
export const { ActionBarContext, useActionBar } = createContext<ActionBarContextValue>()({
  name: "ActionBar",
});

import {
  ActionBarBody,
  ActionBarClose,
  ActionBarContent,
  ActionBarRoot,
  ActionBarSeparator,
  ActionBarTrigger,
  ActionBarValue,
} from "./action-bar";

export type {
  ActionBarBodyProps,
  ActionBarCloseProps,
  ActionBarContentProps,
  ActionBarProps,
  ActionBarSeparatorProps,
  ActionBarTriggerProps,
  ActionBarValueProps,
} from "./action-bar";

export const ActionBar = Object.assign(ActionBarRoot, {
  Body: ActionBarBody,
  Close: ActionBarClose,
  Content: ActionBarContent,
  Separator: ActionBarSeparator,
  Trigger: ActionBarTrigger,
  Value: ActionBarValue,
});

import { ark } from "@ark-ui/react/factory";
import { type AlertRecipeSlot, type AlertVariantProps, alertRecipe } from "@pisagor/recipes/alert";
import type { ComponentProps, ReactNode } from "react";
import type { VariantClassNames } from "../../internal/types";
import { AlertContext, useAlert } from "./alert.context";

// #region Types
type AlertTitleProps = ComponentProps<typeof ark.div>;

type AlertDescriptionProps = ComponentProps<typeof ark.div>;

type AlertActionProps = ComponentProps<typeof ark.div>;

type AlertClassNames = VariantClassNames<AlertRecipeSlot>;

type AlertRootProps = Omit<ComponentProps<typeof ark.div>, "title"> &
  AlertVariantProps & {
    /**
     * Style recipe. Defaults to `alertRecipe` from `@pisagor/recipes/alert`.
     *
     * @defaultValue alertRecipe
     */
    recipe?: typeof alertRecipe;
  };

export interface AlertProps extends Omit<AlertRootProps, "children"> {
  /** Trailing action area. */
  action?: ReactNode;
  /** Description content. */
  description?: ReactNode;
  /** Leading icon, rendered as a direct child so the grid layout aligns. */
  icon?: ReactNode;
  /** Bold title line. */
  title?: ReactNode;
  /** Slot class names */
  classNames?: AlertClassNames;
  /** Extra props forwarded to the alert action element */
  actionProps?: Omit<AlertActionProps, "children" | "className">;
  /** Extra props forwarded to the alert description element */
  descriptionProps?: Omit<AlertDescriptionProps, "children" | "className">;
  /** Extra props forwarded to the alert title element */
  titleProps?: Omit<AlertTitleProps, "children" | "className">;
}
// #endregion

// #region Parts
export function AlertRoot({
  variant,
  children,
  recipe = alertRecipe,
  className,
  ...rest
}: AlertRootProps) {
  const slots = recipe({ variant });

  return (
    <AlertContext value={{ slots }}>
      <ark.div {...rest} className={slots.base({ className })} data-part="root" data-scope="alert">
        {children}
      </ark.div>
    </AlertContext>
  );
}

export function AlertTitle({ children, className, ...rest }: AlertTitleProps) {
  const { slots } = useAlert();

  return (
    <ark.div {...rest} className={slots.title({ className })} data-part="title" data-scope="alert">
      {children}
    </ark.div>
  );
}

export function AlertDescription({ children, className, ...rest }: AlertDescriptionProps) {
  const { slots } = useAlert();

  return (
    <ark.div
      {...rest}
      className={slots.description({ className })}
      data-part="description"
      data-scope="alert"
    >
      {children}
    </ark.div>
  );
}

export function AlertAction({ children, className, ...rest }: AlertActionProps) {
  const { slots } = useAlert();

  return (
    <ark.div
      {...rest}
      className={slots.action({ className })}
      data-part="action"
      data-scope="alert"
    >
      {children}
    </ark.div>
  );
}
// #endregion

// #region Shorthand
export function AlertShorthand({
  variant,
  action,
  actionProps,
  description,
  descriptionProps,
  icon,
  title,
  titleProps,
  className,
  classNames,
  ...rest
}: AlertProps) {
  return (
    <AlertRoot {...rest} className={className} variant={variant}>
      {icon}

      {title !== undefined && (
        <AlertTitle {...titleProps} className={classNames?.title}>
          {title}
        </AlertTitle>
      )}

      {description !== undefined && (
        <AlertDescription {...descriptionProps} className={classNames?.description}>
          {description}
        </AlertDescription>
      )}

      {action !== undefined && (
        <AlertAction {...actionProps} className={classNames?.action}>
          {action}
        </AlertAction>
      )}
    </AlertRoot>
  );
}
// #endregion

// #region Display Names
AlertRoot.displayName = "Alert.Root";
AlertTitle.displayName = "Alert.Title";
AlertDescription.displayName = "Alert.Description";
AlertAction.displayName = "Alert.Action";
AlertShorthand.displayName = "Alert";
// #endregion

import type { AlertRecipe } from "@pisagor/recipes/alert";
import { createContext } from "../../utils";

interface AlertContextValue {
  slots: AlertRecipe;
}

export const { AlertContext, useAlert } = createContext<AlertContextValue>()({
  name: "Alert",
});

import { AlertAction, AlertDescription, AlertRoot, AlertShorthand, AlertTitle } from "./alert";

export type { AlertProps } from "./alert";

export const Alert = Object.assign(AlertShorthand, {
  Action: AlertAction,
  Description: AlertDescription,
  Root: AlertRoot,
  Title: AlertTitle,
});

import { Portal } from "@ark-ui/react/portal";
import type { ReactNode } from "react";
import { Button, type ButtonProps } from "../button";
import type {
  DialogBodyProps,
  DialogCloseTriggerProps,
  DialogContentProps,
  DialogDescriptionProps,
  DialogFooterProps,
  DialogHeaderProps,
  DialogRootProps,
  DialogTitleProps,
  DialogTriggerProps,
} from "../dialog";
import { Dialog } from "../dialog";
import { useDialog } from "../dialog/dialog.context";

// #region Types
export type AlertDialogRootProps = DialogRootProps;

export interface AlertDialogActionProps
  extends DialogCloseTriggerProps,
    Omit<ButtonProps, "variant"> {
  /**
   * The variant of the action button
   *
   * @defaultValue "default"
   */
  variant?: "default" | "destructive";
}

export interface AlertDialogCancelProps
  extends DialogCloseTriggerProps,
    Omit<ButtonProps, "variant"> {}

export interface AlertDialogProps extends Omit<AlertDialogRootProps, "children" | "title"> {
  /** Footer actions (typically Cancel / Action). */
  actions?: ReactNode;
  /** Header description content. */
  description?: ReactNode;
  /** Header title content. */
  title?: ReactNode;
  /** Control that opens the dialog. */
  trigger?: ReactNode;
}
// #endregion

// #region Parts
export function AlertDialogRoot({ children, ...rest }: AlertDialogRootProps) {
  return (
    <Dialog.Root {...rest} role="alertdialog">
      {children}
    </Dialog.Root>
  );
}

export function AlertDialogTrigger(props: DialogTriggerProps) {
  return <Dialog.Trigger {...props} />;
}

export function AlertDialogContent({
  bottomStickOnMobile = true,
  children,
  ...rest
}: DialogContentProps) {
  return (
    <Portal>
      <Dialog.Backdrop />

      <Dialog.Positioner bottomStickOnMobile={bottomStickOnMobile}>
        <Dialog.Content {...rest} bottomStickOnMobile={bottomStickOnMobile} showCloseButton={false}>
          {children}
        </Dialog.Content>
      </Dialog.Positioner>
    </Portal>
  );
}

export function AlertDialogBody({ className, ...rest }: DialogBodyProps) {
  const { slots } = useDialog();

  return (
    <Dialog.Body
      {...rest}
      className={slots.alertBody({ className })}
      data-part="body"
      data-scope="alert-dialog"
    />
  );
}

export function AlertDialogHeader(props: DialogHeaderProps) {
  return <Dialog.Header {...props} data-part="header" data-scope="alert-dialog" />;
}

export function AlertDialogTitle(props: DialogTitleProps) {
  return <Dialog.Title {...props} />;
}

export function AlertDialogDescription(props: DialogDescriptionProps) {
  return <Dialog.Description {...props} />;
}

export function AlertDialogCloseTrigger(props: DialogCloseTriggerProps) {
  return <Dialog.CloseTrigger {...props} />;
}

export function AlertDialogFooter(props: DialogFooterProps) {
  return <Dialog.Footer {...props} data-part="footer" data-scope="alert-dialog" />;
}

export function AlertDialogAction({ variant = "default", ...rest }: AlertDialogActionProps) {
  return <Button {...rest} variant={variant} />;
}

export function AlertDialogCancel(props: AlertDialogCancelProps) {
  return (
    <AlertDialogCloseTrigger asChild>
      <Button {...props} variant="outline" />
    </AlertDialogCloseTrigger>
  );
}
// #endregion

// #region Shorthand
export function AlertDialogShorthand({
  actions,
  description,
  title,
  trigger,
  ...rest
}: AlertDialogProps) {
  return (
    <AlertDialogRoot {...rest}>
      {trigger !== undefined && <AlertDialogTrigger asChild>{trigger}</AlertDialogTrigger>}

      <AlertDialogContent>
        {(title !== undefined || description !== undefined) && (
          <AlertDialogHeader>
            {title !== undefined && <AlertDialogTitle>{title}</AlertDialogTitle>}

            {description !== undefined && (
              <AlertDialogDescription>{description}</AlertDialogDescription>
            )}
          </AlertDialogHeader>
        )}

        {actions !== undefined && <AlertDialogFooter>{actions}</AlertDialogFooter>}
      </AlertDialogContent>
    </AlertDialogRoot>
  );
}
// #endregion

// #region Display Names
AlertDialogRoot.displayName = "AlertDialog.Root";
AlertDialogTrigger.displayName = "AlertDialog.Trigger";
AlertDialogContent.displayName = "AlertDialog.Content";
AlertDialogBody.displayName = "AlertDialog.Body";
AlertDialogHeader.displayName = "AlertDialog.Header";
AlertDialogTitle.displayName = "AlertDialog.Title";
AlertDialogDescription.displayName = "AlertDialog.Description";
AlertDialogCloseTrigger.displayName = "AlertDialog.CloseTrigger";
AlertDialogFooter.displayName = "AlertDialog.Footer";
AlertDialogAction.displayName = "AlertDialog.Action";
AlertDialogCancel.displayName = "AlertDialog.Cancel";
AlertDialogShorthand.displayName = "AlertDialog";
// #endregion

import { ark } from "@ark-ui/react/factory";
import { type AnnouncementVariantProps, announcementRecipe } from "@pisagor/recipes/announcement";
import type { ComponentProps, ReactNode } from "react";
import { AnnouncementContext, useAnnouncement } from "./announcement.context";

// #region Types
type AnnouncementTitleProps = ComponentProps<typeof ark.span>;

type AnnouncementRootProps = Omit<ComponentProps<typeof ark.div>, "title"> &
  AnnouncementVariantProps & {
    /**
     * The ARIA role of the announcement.
     *
     * @defaultValue "status"
     */
    role?: "status" | "alert";
    /**
     * Style recipe. Defaults to `announcementRecipe` from `@pisagor/recipes/announcement`.
     *
     * @defaultValue announcementRecipe
     */
    recipe?: typeof announcementRecipe;
  };

export interface AnnouncementProps extends Omit<AnnouncementRootProps, "children"> {
  /** Optional badge or label rendered before the title. */
  badge?: ReactNode;
  /** Title content rendered inside `Announcement.Title`. */
  title?: ReactNode;
  /** Extra props forwarded to the announcement title element */
  titleProps?: Omit<AnnouncementTitleProps, "children" | "className">;
}
// #endregion

// #region Parts
export function AnnouncementRoot({
  role = "status",
  children,
  recipe = announcementRecipe,
  className,
  ...rest
}: AnnouncementRootProps) {
  const slots = recipe();

  return (
    <AnnouncementContext value={{ slots }}>
      <ark.div
        {...rest}
        className={slots.base({ className })}
        data-part="root"
        data-scope="announcement"
        role={role}
      >
        {children}
      </ark.div>
    </AnnouncementContext>
  );
}

export function AnnouncementTitle({ className, ...rest }: AnnouncementTitleProps) {
