  notifyRegionChange: () => void;
  panelStates: RefObject<Partial<Record<AppShellPlacement, AppShellSideState>>>;
  railStates: RefObject<Partial<Record<AppShellPlacement, AppShellRailState>>>;
  regionResizing: boolean;
