}: AvatarProps) {
  return (
    <AvatarRoot {...rest} shape={shape} size={size}>
      {src && <AvatarImage {...imageProps} alt={alt} className={classNames?.image} src={src} />}

      {fallback !== undefined && (
        <AvatarFallback {...fallbackProps} className={classNames?.fallback}>
