import { type FieldInputProps, FieldInput as InputPrimitive } from "@ark-ui/react/field";
import {
  type InputRecipeSlot,
  type InputRootVariantProps,
  inputRecipe,
  inputRootRecipe,
} from "@pisagor/recipes/input";
import { cn } from "@pisagor/utils";
import type { ChangeEventHandler, RefAttributes } from "react";
import { useClearableInput } from "../../hooks";
import type { VariantClassNames } from "../../internal/types";
import { InputGroupRoot } from "../input-group/input-group-core";
import { useFormControlSurface } from "../surface/use-form-control-surface";
import { InputClearAddon } from "./input-clear-button";

// #region Types
type FormControlVariant = "primary" | "secondary";

type InputClassNames = VariantClassNames<InputRecipeSlot>;

type InputVariantProps = InputRootVariantProps;

export interface InputProps
  extends Omit<FieldInputProps, "size">,
    InputVariantProps,
    RefAttributes<HTMLInputElement> {
  /**
   * Whether to show a clear button when the input has a value.
   *
   * @defaultValue false
   *
   * @remarks
   * In controlled mode, pass `value` and update it via `onChange` or `onValueChange` when clearing.
   */
  clearable?: boolean;
  /** Called with the string value when the input changes. */
  onValueChange?: (value: string) => void;
  /**
   * Style recipe. Defaults to `inputRecipe` from `@pisagor/recipes/input`.
   *
   * @defaultValue inputRecipe
   */
  recipe?: typeof inputRecipe;
  /**
   * Root style recipe. Defaults to `inputRootRecipe` from `@pisagor/recipes/input`.
   *
   * @defaultValue inputRootRecipe
   */
  rootRecipe?: typeof inputRootRecipe;
  /** Slot class names */
  classNames?: InputClassNames;
}
// #endregion

// #region Component
export function Input({
  size = "md",
  variant: variantProp,
  clearable = false,
  defaultValue,
  disabled,
  readOnly,
  type = "text",
  value,
  ref,
  onChange,
  onValueChange,
  recipe = inputRecipe,
  rootRecipe = inputRootRecipe,
  className,
  classNames,
  ...rest
}: InputProps) {
  const resolved = {
    surfaceVariant: useFormControlSurface(),
    variant: variantProp ?? ("primary" as FormControlVariant),
  };

  const { canClear, handleChange, handleClear, mergedRef } = useClearableInput({
    clearable: clearable && type !== "file" && type !== "password",
    defaultValue,
    disabled,
    onChange,
    onValueChange,
    readOnly,
    ref,
    type,
    value,
  });

  const skipClearable = !clearable || type === "file" || type === "password";
  const shellArgs = {
    surfaceVariant: resolved.surfaceVariant,
    variant: resolved.variant,
  };
  const controlProps = { "data-variant": resolved.variant };
  const slots = recipe();

  const changeHandler: ChangeEventHandler<HTMLInputElement> | undefined = skipClearable
    ? onChange || onValueChange
      ? (event) => {
          onChange?.(event);
          onValueChange?.(event.target.value);
        }
      : undefined
    : handleChange;

  if (skipClearable) {
    return (
      <InputPrimitive
        {...rest}
        {...controlProps}
        className={rootRecipe({ className, size, ...shellArgs })}
        data-size={size}
        defaultValue={defaultValue}
        disabled={disabled}
        onChange={changeHandler}
        readOnly={readOnly}
        ref={ref}
        type={type}
        value={value}
      />
    );
  }

  return (
    <InputGroupRoot size={size} variant={variantProp}>
      <InputPrimitive
        {...rest}
        className={slots.clearableRoot({ className: cn(className, classNames?.clearableRoot) })}
        data-size={size}
        defaultValue={defaultValue}
        disabled={disabled}
        onChange={handleChange}
        readOnly={readOnly}
        ref={mergedRef}
        type={type}
        value={value}
      />
      {canClear ? <InputClearAddon onClear={handleClear} /> : null}
    </InputGroupRoot>
  );
}
// #endregion

