   * Whether to show the handle.
   *
   * @defaultValue false
   */
  withHandle?: boolean;
}

export interface ResizableRootProps extends SplitterRootProps {
  /**
   * Style recipe. Defaults to `resizableRecipe` from `@pisagor/recipes/resizable`.
   *
   * @defaultValue resizableRecipe
   */
