// #region Constants
const SIDEBAR_STORAGE_KEY = "sidebar_state";

const SIDEBAR_WIDTH = "16rem";

const SIDEBAR_WIDTH_MOBILE = "18rem";

const SIDEBAR_WIDTH_ICON = "3rem";
// #endregion

// #region Parts
export function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  recipe = sidebarRecipe,
  className,
  style,
  ...rest
}: SidebarProviderProps) {
  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = useState(false);

  const [_open, _setOpen] = useState(defaultOpen);
  const open = openProp ?? _open;
  const setOpen = useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value;
      if (setOpenProp) {
        setOpenProp(openState);
      } else {
        _setOpen(openState);
      }

      localStorage.setItem(SIDEBAR_STORAGE_KEY, String(openState));
    },
    [setOpenProp, open],
  );

  const toggleSidebar = useCallback(() => {
    if (isMobile) {
      setOpenMobile((open) => !open);
    } else {
      setOpen((open) => !open);
    }
  }, [isMobile, setOpen]);

  useHotkey({
    action: () => {
      toggleSidebar();
    },
    hotkey: "mod+B",
  });

  const state = open ? "expanded" : "collapsed";
  const slots = recipe();

  const contextValue = useMemo<SidebarContextProps>(
    () => ({
      isMobile,
      open,
      openMobile,
      setOpen,
      setOpenMobile,
      slots,
      state,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, slots, toggleSidebar],
  );

  return (
    <SidebarContext value={contextValue}>
      <ark.div
        {...rest}
        className={slots.wrapper({ className })}
        data-part="wrapper"
        data-scope="sidebar"
        style={
          {
            "--sidebar-width": SIDEBAR_WIDTH,
            "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
            ...style,
          } as CSSProperties
        }
      />
    </SidebarContext>
  );
}

export function SidebarRoot(props: SidebarProps) {
  const {
    collapsible = "offcanvas",
    placement = "left",
    variant = "sidebar",
    className,
    children,
    ...rest
  } = props;
  const { isMobile, openMobile, setOpenMobile, slots, state } = useSidebar();
  const padded = variant === "floating" || variant === "inset";

  if (collapsible === "none") {
    return (
      <ark.div
        {...rest}
        className={slots.base({ className })}
        data-part="root"
        data-scope="sidebar"
      >
        {children}
      </ark.div>
    );
  }

  if (isMobile) {
    return (
      <Sheet onOpenChange={({ open }) => setOpenMobile(open)} open={openMobile}>
        <Sheet.Content
          {...rest}
          className={slots.mobile()}
          data-mobile="true"
          data-sidebar="sidebar"
          placement={placement === "left" ? "left" : "right"}
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
            } as CSSProperties
          }
        >
          <Sheet.Header className={slots.mobileHeader()}>
            <Sheet.Title>Sidebar</Sheet.Title>
            <Sheet.Description>Displays the mobile sidebar.</Sheet.Description>
          </Sheet.Header>
          <ark.div className={slots.mobileBody()}>{children}</ark.div>
        </Sheet.Content>
      </Sheet>
    );
  }

  return (
    <ark.div
      {...rest}
      className={slots.peer({ className })}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-part="root"
      data-placement={placement}
      data-scope="sidebar"
      data-state={state}
      data-variant={variant}
    >
      <ark.div className={slots.gap({ padded, placement })} data-part="gap" data-scope="sidebar" />
      <ark.div
        className={slots.container({ className, padded, placement })}
        data-part="container"
        data-scope="sidebar"
      >
        <ark.div
          className={slots.inner()}
          data-part="inner"
          data-scope="sidebar"
          data-sidebar="sidebar"
        >
          {children}
        </ark.div>
      </ark.div>
    </ark.div>
  );
}

