// #endregion

// #region Closed
export function Slider({
  variant,
  defaultValue,
  max = 100,
  min = 0,
  showMarkers = false,
  showValue = false,
  tabIndex,
  value,
  children,
  controlProps,
  label,
  markerInterval = 1,
  markerLabels = [],
  rangeProps,
  thumbProps,
  trackProps,
  valueProps,
  onValueChange,
  className,
  classNames,
  ...rest
}: SliderProps) {
  const _values = useMemo(() => {
    if (Array.isArray(value)) {
      return value;
    }
    if (Array.isArray(defaultValue)) {
      return defaultValue;
    }
    return [min, max];
  }, [value, defaultValue, min, max]);

  const handleValueChange = onValueChange
    ? (details: Parameters<NonNullable<SliderRootProps["onValueChange"]>>[0]) =>
        onValueChange(details.value)
    : undefined;

  return (
    <SliderRoot
      {...rest}
      className={className}
      defaultValue={defaultValue}
      max={max}
      min={min}
      onValueChange={handleValueChange}
      value={value}
      variant={variant}
    >
      {(label !== undefined || showValue) && (
        <SliderHeader className={classNames?.header}>
          {label !== undefined && (
            <Field.Label>
              <SliderPrimitive.Label>{label}</SliderPrimitive.Label>
            </Field.Label>
          )}

          {showValue && (
            <Field.Label asChild>
              <SliderValue {...valueProps} className={classNames?.value} />
            </Field.Label>
          )}
        </SliderHeader>
      )}

      {children}

      <SliderControl {...controlProps} className={classNames?.control}>
        <SliderTrack {...trackProps} className={classNames?.track}>
          <SliderRange {...rangeProps} className={classNames?.range} />
        </SliderTrack>

        {Array.from({ length: _values.length }, (_, index) => {
          const key = `slider-thumb-${index}`;

          return (
            <SliderThumb
              {...thumbProps}
              className={classNames?.thumb}
              index={index}
              key={key}
              tabIndex={tabIndex ?? undefined}
            >
              <SliderPrimitive.HiddenInput />
            </SliderThumb>
          );
        })}
      </SliderControl>

      {showMarkers && (
        <SliderMarkerGroup className={classNames?.markerGroup}>
          {Array.from({ length: max + 1 }, (_, index) => (
            <SliderMarker
              className={classNames?.marker}
              data-interval={index % markerInterval === 0 ? undefined : ""}
              key={String(index)}
              value={index}
            >
              <SliderMarkerTick className={classNames?.markerTick} />

              <SliderMarkerLabel className={classNames?.markerLabel}>
                {markerLabels?.[index] ?? index}
              </SliderMarkerLabel>
            </SliderMarker>
          ))}
        </SliderMarkerGroup>
      )}
    </SliderRoot>
  );
}
// #endregion

